import json, math

def is_sq(x):
    if x < 0:
        return False
    r = math.isqrt(x)
    return r * r == x

def expr(n):
    return (n**3 + 39*n - 2) * math.factorial(n) + 17 * 21**n + 5

def isprime(p):
    return p > 1 and all(p % d for d in range(2, int(p**0.5) + 1))

# Find a prime p such that for all n >= p the expression is a non-residue mod p.
# For n >= p, n! = 0 mod p, so expr = 17*21^n + 5 mod p, periodic in n with period dividing p-1.
proof = None
for p in range(2, 500):
    if not isprime(p):
        continue
    ok = True
    for n in range(p, p + max(p - 1, 1) + 1):
        v = (17 * pow(21, n, p) + 5) % p
        if v == 0 or pow(v, (p - 1) // 2, p) == 1 if p > 2 else True:
            ok = False
            break
    if ok:
        proof = p
        break

if proof is None:
    print("UNSUPPORTED")
else:
    sols = [n for n in range(0, proof) if is_sq(expr(n))]
    sols_pos = [n for n in sols if n >= 1]
    print(json.dumps({
        "final_answer": ", ".join(map(str, sols_pos)),
        "evidence": {
            "prime_modulus_excluding_n_ge_p": proof,
            "checked_range": [0, proof - 1],
            "squares_in_range_including_0": sols,
            "n1_value": expr(1),
        }
    }))
